#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *a = (long long *)malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    qsort(a, n, sizeof(long long), cmp);

    long long total_trios = 0;

    for (int k = 2; k < n; k++) {
        int i = 0;
        int j = k - 1;
        while (i < j) {
            if (a[i] + a[j] > a[k]) {
                total_trios += (j - i);
                j--;
            } else {
                i++;
            }
        }
    }

    printf("%lld\n", total_trios);

    free(a);
    return 0;
}
